# Correspondence
# ------------------------------------------------------------------------------------------------
@correspondence_router.get("")
def list_correspondence(hazard_id: str | None = Query(default=None),
                        incident_id: str | None = Query(default=None)) -> list[dict[str, Any]]:
    with session_scope() as s:
        q = select(Correspondence)
        if hazard_id:
            q = q.where(Correspondence.hazard_id == hazard_id)
        if incident_id:
            q = q.where(Correspondence.incident_id == incident_id)
        rows = list(s.exec(q.order_by(Correspondence.created_at)).all())
        return [obs.redact(correspondence_out(m)) for m in rows]


@correspondence_router.post("/draft")
async def draft(body: CorrespondenceIn, settings: Settings = Depends(settings_dep)) -> dict[str, Any]:
    """Draft a message about one incident. Nothing is sent, here or anywhere."""
    with session_scope() as s:
        incident = s.get(Incident, body.incident_id)
        if incident is None:
            raise HTTPException(404, "incident not found")
        nbr = s.get(Neighbour, incident.neighbour_id)
        hazard = s.get(Hazard, incident.hazard_id)
        hazard_record = _hazard_record(s, hazard)
        neighbour_record = {
            "id": incident.neighbour_id,
            "name": nbr.name if nbr else incident.neighbour_id,
            "address": incident.address, "unit": nbr.unit if nbr else "",
            "access_notes": nbr.access_notes if nbr else "",
            "age_band": nbr.age_band if nbr else "", "lives_alone": bool(nbr.lives_alone) if nbr else None,
            "mobility": nbr.mobility if nbr else "", "conditions": list(nbr.conditions or []) if nbr else [],
            "power_dependent": bool(nbr.power_dependent) if nbr else None,
            "contact_name": nbr.contact_name if nbr else "", "contact_phone": nbr.contact_phone if nbr else "",
            "contact_relation": nbr.contact_relation if nbr else "",
        }
        calls = list(s.exec(select(CheckCall).where(
            CheckCall.neighbour_id == incident.neighbour_id, CheckCall.sweep_id == incident.sweep_id,
            CheckCall.callee == "neighbour").order_by(CheckCall.attempt)).all())
        attempts = [{"at": c.started_at, "outcome": c.outcome or c.status, "status": c.status} for c in calls]
        packet_row = None
        if incident.escalation_id:
            packet_row = s.exec(select(HandoffPacket).where(
                HandoffPacket.escalation_id == incident.escalation_id)).first()
        packet = {
            "last_contact_at": packet_row.last_contact_at if packet_row else None,
            "last_words": packet_row.last_words if packet_row else "",
            "concerns": list(packet_row.concerns or []) if packet_row else [],
            "attempts_summary": list(packet_row.attempts_summary or []) if packet_row else attempts,
            "recommended_action": packet_row.recommended_action if packet_row else incident.summary,
        }
        visit = _visit_record(s, incident)
        hazard_id = incident.hazard_id

    client = build_client(settings)
    captain = settings.BLOCK_CAPTAIN_NAME
    kind = body.kind.strip().lower()
    if kind == "family":
        msg = await draft_family_update(
            hazard_id=hazard_id, hazard=hazard_record, neighbour=neighbour_record, visit=visit,
            incident_id=body.incident_id, channel=body.channel or "sms", captain_name=captain,
            to_name=body.to_name, client=client,
        )
    elif kind == "agency":
        msg = await draft_agency_message(
            hazard_id=hazard_id, hazard=hazard_record, neighbour=neighbour_record, packet=packet,
            agency=body.agency, incident_id=body.incident_id,
            channel=body.channel or "call_script", captain_name=captain, client=client,
        )
    else:
        msg = await draft_contact_message(
            hazard_id=hazard_id, hazard=hazard_record, neighbour=neighbour_record, attempts=attempts,
            incident_id=body.incident_id, channel=body.channel or "sms", captain_name=captain,
            client=client,
        )

    with session_scope() as s:
        row = Correspondence(**msg)
        s.add(row)
        s.flush()
        out = obs.redact(correspondence_out(row))
    from app.events.bus import bus
    bus.publish(hazard_id=hazard_id, type="correspondence.drafted",
                payload={"message_id": out.get("id"), "kind": kind, "incident_id": body.incident_id})
    return out


@correspondence_router.get("/{message_id}")
def get_correspondence(message_id: str) -> dict[str, Any]:
    with session_scope() as s:
        msg = s.get(Correspondence, message_id)
        if msg is None:
            raise HTTPException(404, "message not found")
        return obs.redact(correspondence_out(msg))


@correspondence_router.post("/{message_id}/approve")
def approve_correspondence(message_id: str, body: ApproveIn) -> dict[str, Any]:
    """A human approves a draft for a human to send.

    Approving is not sending, and `sent_at` stays null: there is no send path in this codebase. What
    approval means is that a named person read the words and is willing to have them go out under
    their name, which is exactly the boundary `HandoffPacket.released_at` draws.
    """
    from app.orchestrator import escalate as ladder

    with session_scope() as s:
        msg = s.get(Correspondence, message_id)
        if msg is None:
            raise HTTPException(404, "message not found")
        try:
            msg.approved_by = ladder._validate_releaser(body.approved_by)  # noqa: SLF001
        except ladder.ReleaseRefused as exc:
            raise HTTPException(400, str(exc)) from exc
        s.add(msg)
        s.flush()
        return obs.redact(correspondence_out(msg))


def _visit_record(session: Session, incident: Incident) -> dict[str, Any]:
    """What actually happened at the address, from the dispatch rows. Never a narrative.

    An unarrived dispatch says so; that is the honest answer and it is what stops a family update
    saying somebody has been round when nobody has.
    """
    rows = list(session.exec(select(Dispatch).where(Dispatch.incident_id == incident.id)
                             .order_by(Dispatch.proposed_at)).all())
    arrived = [d for d in rows if d.arrived_at is not None]
    if not arrived:
        return {"who": "", "arrived_at": None,
                "found": "nobody has been to the address yet",
                "actions": "nothing has been delivered or done at the address",
                "outstanding": ", ".join(incident.needs or []) or "not recorded"}
    latest = arrived[-1]
    asset = session.get(Asset, latest.asset_id)
    return {
        "who": f"{asset.call_sign} ({asset.operator_name})" if asset else latest.asset_id,
        "arrived_at": latest.arrived_at,
        "found": incident.summary or "not recorded",
        "actions": f"{asset.call_sign} attended and covered {', '.join(incident.needs or []) or 'the request'}"
                   if asset else "attended",
        "outstanding": incident.resolution or "the incident is still open",
    }
